import unittest

from django.core.exceptions import ValidationError


class TestValidationError(unittest.TestCase):
    def test_messages_concatenates_error_dict_values(self):
        message_dict = {}
        exception = ValidationError(message_dict)
        self.assertEqual(sorted(exception.messages), [])
        message_dict['field1'] = ['E1', 'E2']
        exception = ValidationError(message_dict)
        self.assertEqual(sorted(exception.messages), ['E1', 'E2'])
        message_dict['field2'] = ['E3', 'E4']
        exception = ValidationError(message_dict)
        self.assertEqual(sorted(exception.messages), ['E1', 'E2', 'E3', 'E4'])

    def test_equality_with_same_messages(self):
        self.assertEqual(ValidationError('Error message'), ValidationError('Error message'))

    def test_equality_with_same_list_messages_different_order(self):
        self.assertEqual(
            ValidationError(['Error 1', 'Error 2']),
            ValidationError(['Error 2', 'Error 1'])
        )

    def test_equality_with_same_dict_messages_different_order(self):
        self.assertEqual(
            ValidationError({'field1': ['Error 1'], 'field2': ['Error 2']}),
            ValidationError({'field2': ['Error 2'], 'field1': ['Error 1']})
        )

    def test_inequality_with_different_messages(self):
        self.assertNotEqual(ValidationError('Error 1'), ValidationError('Error 2'))

    def test_equality_with_nested_validation_errors(self):
        self.assertEqual(
            ValidationError({'field1': ValidationError(['Error 1', 'Error 2'])}),
            ValidationError({'field1': ['Error 2', 'Error 1']})
        )

    def test_equality_with_non_field_errors(self):
        self.assertEqual(
            ValidationError({'__all__': ['Error 1', 'Error 2']}),
            ValidationError(['Error 2', 'Error 1'])
        )
